(function(root){
 const step=(title,actions,expect,help)=>({title,actions,expect,...(help?{help}:{})});
 const lessons=[
 {id:'shared-projects',area:'Organize work',title:'Inspect and test shared project context',minutes:'About 12–18 min',source:'projects',controls:['Project sources','Project instructions','Share / membership','New project chat'],summary:'Share a fictional trial project with a test account you control, then inspect access and context.',steps:[
 {title:'Sharing has an audience',body:['Use a new project containing only a fictional picnic plan and a rule to use short lists. Sharing a project is different from sharing one conversation or connecting a local folder.','You need a second account you control, or an existing authorized test collaborator, to test another person’s view. Without one, you can inspect controls but cannot claim to have verified recipient access.'],expect:'You can identify the project, its sources and the intended test audience.'},
 step('Prepare and inspect',['Create a trial project, add a fictional packing note and save a short-list instruction.','Open its Share or membership controls if offered. Read the actual audience and roles; do not assume a link is private.','Check whether shared sources, chats and instructions are described in the dialog before inviting anyone.'],'You know what the displayed sharing action will expose.','If sharing is unavailable, record unavailable. A shared chat link is not a substitute for a shared-project membership test.'),
 step('Test the recipient view',['Invite only your controlled test account, or a collaborator who has agreed to this trial, using the narrowest suitable role.','Open the project as that recipient and inspect the shared sources and visible chats. Start a new project chat asking about the fictional packing note.','Compare its response with the source and short-list rule. Do not infer that private chats outside the project were shared.'],'You checked actual recipient access and project context.'),
 step('Remove trial access',['Return as owner, remove the trial membership or revoke its sharing link as appropriate.','Refresh the recipient’s view and inspect whether access remains through another membership or link. Preserve your original source note.','Record what was visible and what remained unavailable; an answer alone cannot prove every possible scope boundary.'],'You verified the intended access lifecycle.')],transfer:'For real collaboration, inspect the audience and shared sources, then verify access from an intended recipient’s account.'},
 {id:'gpts',area:'Organize work',title:'Inspect and try an available GPT',minutes:'About 8–12 min',source:'gptMigration',controls:['GPT discovery / existing GPT','Details / creator','New conversation','Capability / action notice'],summary:'Evaluate an existing specialized assistant and distinguish it from a skill or plugin.',steps:[
 {title:'Check the current lifecycle first',body:['GPTs are specialized assistants with their own configured behavior and capabilities. They differ from skills that supply a method and plugins that package capabilities.','GPT availability and migration are changing. Read the current notices in your account and official migration guide. This exercise uses an existing available GPT; it does not require creating or publishing a new one.'],expect:'You know which product object you are evaluating and whether it is available.'},
 step('Inspect one candidate',['Open GPT discovery or an existing GPT where your ChatGPT account exposes it. Choose a writing or learning assistant suitable for a fictional picnic invitation.','Read its name, creator, description and any external action/data-sharing notice.','Choose a task that needs no external account actions. If only a replacement plugin/skill is available, use its separate tutorial and mark this GPT trial unavailable.'],'You selected an identifiable assistant whose stated purpose fits the task.'),
 step('Compare behavior with its purpose',['Start a conversation with that GPT. Ask for a short invitation using four people, Saturday noon and a meeting place still to be confirmed.','Check its response for the constraints, invented details and the behavior promised by its description.','Ask for one targeted revision and inspect the actual change. Decline an unexpected external action.'],'You evaluated a concrete result rather than trusting a specialized name.'),
 step('Choose where to reuse the workflow',['Locate how you would reopen this GPT, if still supported.','Explain which part of the experience came from its configured behavior and which came from your own request; do not infer hidden instructions.','If you own an older GPT, inspect the migration guide separately before moving anything: capabilities and sharing do not automatically transfer.'],'You can decide whether the assistant is useful without confusing it with another reusable object.')],transfer:'Evaluate any specialized assistant using a small task, known constraints and its actual permissions.'},
 {id:'deep-research',area:'Everyday tasks',title:'Run Deep research and audit the report',minutes:'About 20–30 min plus research waiting',source:'webSearch',controls:['Work','Plugins → Deep research','Try now','Report / citations','Follow-up'],summary:'Investigate a bounded question, open supporting sources and repair one weak claim.',steps:[
 {title:'Choose a question that needs investigation',body:['Deep research is useful for a question requiring several sources and a reviewable report. A polished report still needs source checks.','Compare three practical ways a four-person household could reduce food waste over a month. Ask for effort, evidence and limitations, without paid purchases or account connections.'],expect:'You have a bounded investigation and criteria for reviewing it.'},
 step('Select the actual research feature',['Switch to Work, open Plugins and inspect Deep research. Install/enable it if wanted, then use Try now. On supported web, inspect the + menu’s Deep research entry instead.','Describe the comparison, timeframe and desired report with citations; answer scope questions before it begins.','Inspect the selected capability and research activity. An ordinary answer with links is not proof that Deep research ran.'],'You deliberately invoked the available research workflow.','If neither surface offers the feature, record unavailable. A normal web-search comparison is useful but belongs to its own tutorial.'),
 step('Audit the report',['When the report finishes, identify its recommendation and open at least two cited sources supporting important claims.','Check publication dates, whether the source actually discusses households and which evidence supports each conclusion.','Identify one unsupported inference or missing limitation; ask for a correction or an explicit uncertainty label.'],'You checked evidence and scope rather than only the report’s presentation.'),
 step('Apply and preserve the result',['Choose one method and adapt it to a fictional week of meals. Check that the proposed steps follow the verified evidence.','Save/download the report where offered, or keep its chat and a note of the checked sources.','Record the research date and one unresolved question before using the recommendation.'],'You have a traceable result and an actionable use for it.')],transfer:'Use Deep research for a real bounded comparison and audit the sources behind its decision-driving claims.'},
 {id:'maps',area:'Everyday tasks',title:'Explore a map and verify its places',minutes:'About 10–15 min',source:'visualizations',references:['visualizations','webSearch'],controls:['Available map / Visualize','Place markers','Zoom / pan','Source links'],summary:'Map three public places, operate the map and check location evidence.',steps:[
 {title:'A map needs places and geographic evidence',body:['A geographic visual helps compare locations. A marker on an attractive map can still be misplaced or outdated.','Choose a city and three public places: a library, park and museum. Use their official public addresses; no personal location is needed.'],expect:'You know which places and addresses the map should represent.'},
 step('Find places, then request a map',['Use current search to identify the three public venues and open their official address pages. Keep the links and full addresses.','Select an available map capability or @Visualize and request a geographic view using those verified places, labeled markers and source links.','Inspect whether it produced an actual geographic map with controls, a static diagram or only a list.'],'You can identify the actual output type.','If geographic maps are unsupported, keep the sourced list as a fallback and record the map feature unavailable. A schematic is not a verified geographic map.'),
 step('Operate and compare',['Pan and zoom the map. Select each marker and compare its label/address with the official source.','Check that markers are in the intended city and that similarly named venues were not substituted.','If routes or travel times appear, inspect their source, travel mode and currency; a straight line between markers does not establish a route.'],'You verified both the controls and the places represented.'),
 step('Use a real constraint',['Choose two venues you might visit on the same day. Check current opening information on their official pages.','Ask for a revised view or legend if a place is unclear, then verify that marker again.','Keep uncertainty explicit where precise coordinates or routing were not verified.'],'You can use the map for a limited planning decision with checked evidence.')],transfer:'For a real outing, verify each venue and relevant times independently before relying on a generated map.'},
 {id:'sites-publish',area:'Create useful work',title:'Publish a trial Site and verify its audience',minutes:'About 12–18 min',source:'sitePublishing',references:['sitePublishing','siteManagement'],prerequisites:['sites'],controls:['Site version','Publish','Who has access / Share','Deployment URL','Unpublish'],summary:'Publish a fictional checklist deliberately, inspect the live link and remove the trial deployment.',steps:[
 {title:'Publishing creates a live deployment',body:['Use the fictional checklist from the Site-preview tutorial. Remove personal information and inspect its content before publishing. A deployment URL is production, even during a trial.','Visitor access and editing access are separate. Decide the narrowest supported audience; you do not need public access to practice publishing.'],expect:'You have a tested version and an intended audience.'},
 step('Inspect audience, then publish',['Open the saved Site and inspect its sharing/audience controls. Read what each offered option permits.','Choose the limited audience you want and use Publish for the tested version. Review the confirmation before proceeding.','Record the actual deployment URL and version. If publishing is unavailable, keep the saved preview and record unavailable.'],'You can distinguish a saved version from a deployment.','If the interface cannot provide your required audience, stop rather than assume a difficult-to-guess URL limits access.'),
 step('Test as a visitor',['Open the deployment link in a separate browser session using the appropriate authorized account, or signed out if you deliberately chose public access.','Check the actual access outcome, item labels, two checked items and Reset. Check a narrow window too.','For restricted access, inspect a signed-out session or controlled uninvited account and verify that it cannot open the Site.'],'You tested actual visitor access and behavior; owner access alone was insufficient.'),
 step('Take the trial offline',['In the Site’s management/settings controls, locate Unpublish or the current deployment-removal action. Read whether it removes just the deployment or also saved work.','Unpublish the trial if you do not want it live. Reopen its URL in a fresh session to verify the result.','Keep the saved version where supported. Review audience again before a later publication.'],'You know the trial’s final publication state and preserved work.')],transfer:'Publish only a reviewed version, verify the intended audience and know how to take it offline.'},
 {id:'browser-extension',area:'See and work',title:'Use a connected browser tab as context',minutes:'About 10–15 min',source:'browserExtension',controls:['Settings → Computer Use','Browser extension setup','@ browser / tab','Selected text','Browser task activity'],summary:'Connect a supported browser, select one public tab and verify what was read.',steps:[
 {title:'Your browser profile is distinct from the built-in browser',body:['The extension connects a supported regular browser to the desktop app. It can expose existing tabs and signed-in context within its permissions. The in-app browser uses a different profile.','Use one public documentation page for this read-only trial. No private account or form submission is needed.'],expect:'You can identify which browser/profile will provide the context.'},
 step('Set up and inspect',['Open Settings → Computer Use in the desktop app. Select your supported browser and follow its extension installation/enable flow.','Review the extension permissions and confirm the correct browser profile. Open a public OpenAI documentation page there.','Return to the desktop app and inspect whether this browser appears in the @ menu or connection controls.'],'The intended browser is actually connected.','If the browser or extension is unavailable, record that. Opening the same URL in an in-app tab does not test the external extension.'),
 step('Select a tab and verify a reading',['Mention the actual open browser tab using the supported picker. Ask for its page title and a summary of one named section, without navigating elsewhere.','Inspect the selected tab identity and activity; compare the answer directly with the page.','Where supported, select one paragraph and use Ask ChatGPT/side chat to ask about that passage. Opera does not provide side chat; use the desktop task there.'],'You checked both the intended tab and the actual reading.'),
 step('Manage the connection',['Inspect the browser’s Manage controls and any site-specific access settings.','If the extension was installed only for this trial, disable it through the supported extension/settings controls if desired and check the resulting connection state. Preserve a pre-existing setup.','Close the trial tab when finished; closing a tab alone is not the same as revoking extension access.'],'You understand the scope and final state of your connection.')],transfer:'Select the exact tab or passage needed for a task and check the source before allowing further actions.'},
 {id:'computer-use',area:'See and work',title:'Let AI operate one harmless desktop task',minutes:'About 10–15 min',source:'computerUse',controls:['Settings → Computer Use','@Computer / app picker','App permission','Stop','Foreground window'],summary:'Have the assistant type a fictional note in Notepad, then stop and inspect it yourself.',steps:[
 {title:'Computer Use can act on an app',body:['Computer Use can inspect and operate supported apps. A screenshot alone supplies visual context; it does not demonstrate app control.','Open a new Notepad window with no sensitive content. On Windows, the task uses the foreground desktop; avoid competing mouse/keyboard activity while it acts.'],expect:'You have chosen the app, scope and observable outcome.'},
 step('Enable and select deliberately',['Inspect Computer Use settings and its current availability. Follow the supported setup only if you want to allow it.','In a supported Work/Codex chat, select @Computer or the actual Notepad app where offered.','Request only typing three fictional picnic items into the blank Notepad window. Do not authorize saving over an existing file or interacting with other apps.'],'The task targets the intended harmless window.','If the platform or workspace blocks control, record unavailable. A prose simulation or shell-created file does not demonstrate typing through the app.'),
 step('Observe and stop',['Inspect any app permission prompt and the selected window before letting it continue.','Observe its actual typing. Use Stop if the target or action differs from your request; do not assume Stop undoes earlier input.','When the task ends, check all three items in Notepad yourself. Compare the real app state with the assistant’s report.'],'You verified a real UI action and know how to interrupt it.'),
 step('Finish in a known state',['Decide whether to save the fictional note yourself or close the unsaved trial window.','Review any persistent app permission you granted and restore its earlier state if that was your intention.','Explain why this task needed app interaction and what would have been simpler with a file tool.'],'You can choose Computer Use for an appropriate task and inspect its effects.')],transfer:'Give a small app task with a clear boundary, watch the actual target and verify the resulting state.'},
 {id:'private-signin',area:'See and work',title:'Use private website sign-in and inspect the session',minutes:'About 8–12 min',source:'browser',references:['browser','dotComputer'],controls:['Sign-in request','Private sign-in form / takeover','Website domain','Passwords where offered','Sign out'],summary:'Sign in through a supported browser handoff without putting credentials into chat.',steps:[
 {title:'Credentials and task context take different routes',body:['A cloud browser has its own sessions; your local browser’s login does not automatically transfer. A saved login is also different from an active session.','Use a low-risk test website account you control in a supported Work cloud/browser experience. Do not create an account or provide private content solely to satisfy this lesson.'],expect:'You know which account, domain and browser session you intend to use.'},
 step('Inspect the handoff',['Ask the supported browser task to open the account’s website and pause for sign-in, with no account changes.','When its sign-in request appears, inspect the actual domain and intended account. Use Not now/cancel if they do not match.','Open the private form or offered takeover/on-page sign-in route. Do not paste passwords or verification codes into the conversation.'],'You identified a supported private entry route.','If no secure handoff is offered, record unavailable and stop this trial. A chat asking for credentials is not the private form.'),
 step('Sign in and return control',['Enter your credentials and required verification directly in the sign-in flow. Saving to Passwords, if offered, is optional; leave it off for this trial unless wanted.','Complete the offered Done/return-control step. Ask only to confirm the signed-in account identity without reading unrelated content.','Inspect the browser yourself to verify the account and session.'],'You verified the active session rather than assuming sign-in succeeded.'),
 step('End or retain the session deliberately',['Sign out of the trial website if you do not want its session retained, then inspect the signed-out page.','If you saved a trial login, inspect its owning Passwords controls and remove only that login if desired. Signing out and removing a saved login are separate actions.','Keep credentials out of any lesson note or screenshot.'],'You know which session or saved-login state remains.')],transfer:'Use only the intended website’s private sign-in route, verify the account and deliberately manage retained sessions.'}
 ];
 lessons.push(
 {id:'cloud-computer',area:'See and work',title:'Inspect a graphical cloud computer and take over',minutes:'About 10–15 min',source:'dotComputer',references:['dotComputer','browser'],controls:['Cloud computer / Open computer','Take over','Return control','Remote browser'],summary:'Use a public-page task to distinguish a remote graphical computer from your own desktop.',steps:[
 {title:'Identify the actual remote surface',body:['A graphical cloud computer has its own browser and files. A Codex cloud coding environment or local in-app tab is not necessarily the same graphical surface.','Use an eligible dot/cloud-computer experience or supported Work browser handoff. The trial only opens a public documentation page. Access varies; no purchase is required for this course.'],expect:'You know which remote surface is available to you.'},
 step('Open and inspect',['Ask the supported cloud task to open a public OpenAI documentation page and pause for inspection.','Use Open computer or the offered browser handoff. In a dot, inspect its profile → Computers.','Read the remote URL/title and compare with your local browser. Do not assume local signed-in sessions or files were transferred.'],'You inspected an actual remote graphical surface.','If you only have a text task or file container without a graphical view, record this graphical feature unavailable.'),
 step('Take over and return',['Select Take over if offered; merely viewing the computer does not give mouse/keyboard control.','Use the remote page’s search or scroll yourself, without signing in or submitting data. Observe its response.','Select Return control or the surface’s Done control, then ask the assistant to summarize the visible section.'],'You deliberately switched control and checked a harmless remote interaction.'),
 step('End the trial',['Inspect the task’s result and stop any remaining trial work. Close the viewer if desired.','Note which actions happened remotely and which remained on your computer. Closing a viewer is not proof a background task stopped.','Keep any trial files only in their intended environment; do not assume they downloaded locally.'],'You can account for the remote task and its final state.')],transfer:'Use a cloud graphical surface only when it serves the task, and verify the current controller, browser session and output location.'},
 {id:'remote-connections',area:'See and work',title:'Connect to your computer from another device',minutes:'About 15–20 min',source:'remoteConnections',controls:['Settings → Connections','Control this PC','Pairing QR / verification','Host selector','Connected devices'],summary:'Pair a supported device with a host you own, read a trial file and inspect revocation.',steps:[
 {title:'The connected host supplies the files and tools',body:['Remote connections let another supported device reach work on your own host. They differ from a storage-service connection and from a cloud computer.','You need a second supported device you control, the same account/workspace and an online host running the desktop app. If you lack those, record unavailable; do not expose a server publicly as a workaround.'],expect:'You can name the controller device and the host that will execute work.'},
 step('Pair through the owning settings',['On the host, create a fictional host-trial.txt file in a dedicated practice folder. Open Settings → Connections → Control this PC/Mac and select Set up or Add where offered.','Review the access request and complete the app’s QR/verification flow from your supported second device. Confirm account, workspace and host identity.','Keep pairing codes in the setup flow. Inspect the resulting connected-device entry.'],'You have an identifiable authorized device pairing.'),
 step('Verify where work happens',['On the second device, open Codex/Remote or Control other devices as your surface offers and select the intended host and practice project.','Request a read of host-trial.txt with no edits. Compare the actual content with the file on the host.','Inspect the task’s host label and permissions. A synchronized chat alone does not prove local file access.'],'You verified a task using the intended host’s resources.'),
 step('Manage access afterward',['On the host, reopen Connections and inspect paired devices and the remote-access switch.','If this was a trial-only pairing, remove/revoke that device through the available control and verify it can no longer connect. Preserve pre-existing pairings.','Distinguish offline status, turning remote access off and removing a device pairing; they need not have the same effect.'],'You deliberately managed the trial access lifecycle.')],transfer:'Before remote work, confirm the selected host and resources; afterward, know which device permissions remain.'},
 {id:'custom-pets',area:'Speak and personalize',title:'Create and try a custom animated Pet',minutes:'About 15–25 min plus generation',source:'pets',prerequisites:['pets'],controls:['Pets settings','Create / pet creation workflow','Preview / Library','Select Pet','Hide'],summary:'Create a simple companion, inspect its animation and restore your earlier selection.',steps:[
 {title:'A Pet is an interface companion',body:['Use a small original character, such as a friendly blue paper bird. A custom Pet needs supported animation assets; a single illustration is not a completed Pet.','Note the Pet or Mini selection you currently use. This trial does not require publishing a character or changing model settings.'],expect:'You know the desired character and which selection to restore.'},
 step('Start the supported creation route',['Open Pets settings and inspect the available creation controls, or select the installed Pet-creation workflow where offered.','Describe the paper bird, its simple shape and readable movement. Ask for a Pet for this app, not just an image.','Inspect the generated preview/artifact and its reported validation or installation state before activation.'],'You can distinguish an image from a usable Pet artifact.','If custom creation is unavailable, use an existing Pet for its separate lesson and record custom creation unavailable.'),
 step('Try the animated result',['Select the custom Pet through its supported picker. Observe idle and active behavior while running a harmless short chat.','Inspect its scale, edges, movement and floating controls. Note any clipping, missing animation or unreadable status.','Request one concrete repair if needed, then reselect the revised artifact and check that behavior again.'],'You inspected the actual animated companion rather than only its thumbnail.'),
 step('Restore or keep it',['Return to Pets and restore your earlier selection or deliberately keep the new one. Try Hide and verify the overlay disappears.','Locate the saved custom Pet in its Library/picker for later reuse. Deleting a Library artifact and hiding the overlay are different actions.','Remove only your own trial artifact if unwanted and the owning controls permit it.'],'You know the artifact’s saved state and the current overlay choice.')],transfer:'Create a companion whose shape and animation remain readable at the size you actually use.'},
 {id:'micro',area:'Speak and personalize',title:'Use Codex Micro hardware controls',minutes:'About 10–15 min',source:'microHardware',controls:['Supported Micro device','Settings → Codex Micro','Agent Key','Dial','Command Key mapping'],summary:'Pair a compatible controller, switch chats and try one reversible command mapping.',steps:[
 {title:'Micro and Mini are different',body:['Codex Micro is a compatible physical controller. Mini is the floating chat-control selection described in the Pets lesson.','This hardware trial requires a supported Micro you already have; buying one is not a course requirement. Without hardware, read the distinction and record unavailable rather than claim a device trial.'],expect:'You know which physical device and app feature this lesson concerns.'},
 step('Connect and inspect',['With the desktop app open, turn on the supported device and connect through USB-C or its documented Bluetooth pairing flow.','Follow the detected-device setup, then open Settings → Codex Micro. Inspect its current key and dial assignments.','Keep the original layout recorded; do not use approval/decline actions for this first trial.'],'The app detects the actual controller.'),
 step('Operate a harmless command',['Use an Agent Key to select a known trial chat and inspect which chat becomes active.','Try the dial’s current navigation behavior and identify the focused control before selecting it.','Map one available command to a harmless action such as showing the sidebar. Trigger it and verify the effect.'],'You operated a physical input and checked the configured result.'),
 step('Restore the mapping',['Restore the command assignment you changed, preserving other custom mappings.','Inspect how the device indicates the selected chat’s state; compare the displayed app state instead of guessing from color alone.','Disconnect if desired and verify ordinary mouse/keyboard interaction still works.'],'You understand the device’s mapping and its final setup.')],transfer:'Use a hardware shortcut only after checking its current assignment and the chat it targets.'},
 {id:'git',area:'Developer workflows',title:'Track a local change with Git',minutes:'About 20–30 min',source:'git',references:['git','review'],prerequisites:['local-folders'],controls:['Practice folder','Git status / Changes','Stage','Commit','Branch selector'],summary:'Create a small repository, inspect a diff, stage one file and verify a local commit.',steps:[
 {title:'Working files, staging and history',body:['A repository tracks snapshots. Working files are what is on disk; staging selects what enters the next commit; a commit records that selected snapshot locally. A branch names a line of history.','Use a new Git Trial folder with a fictional packing-list README. A downloaded ZIP is ordinary files without repository history; do not initialize Git in an unrelated folder or assume it is already a checkout.'],expect:'You can describe the three states and the isolated practice location.'},
 step('Create an initial snapshot',['Open Git Trial in Codex. Ask the assistant to check Git availability and the exact repository root, then initialize only this empty trial folder if needed.','Have it create README.md with three packing items. Inspect the file and status in the app’s Git/review view or the assistant’s command output.','Direct it to stage that file and create the initial commit. Use your intended Git identity if setup is requested; do not invent an identity. Inspect the commit ID and clean status.'],'You have a verified initial local snapshot.','If Git is missing, use its official installation route and restart the app before retrying. File creation alone is not a Git commit.'),
 step('Inspect and stage a precise change',['Change one packing item yourself or direct the assistant to do so. Open Unstaged/Changes and inspect the exact removed and added lines.','Stage only README.md using the app control or an assistant-run file-specific command. Inspect Staged to confirm the selection.','Explain which change would enter the next commit and which files remain outside it.'],'You connected the disk change to its staged diff.'),
 step('Commit, then create a branch',['Create a short descriptive commit and inspect its recorded diff and ID. Confirm the working state is clean.','Create and switch to a practice branch such as picnic-notes using available branch controls or assistant-run Git commands. Inspect the selected branch.','Make a small second change there and inspect status. A branch switch does not by itself create a new commit.'],'You can distinguish a branch name from a recorded snapshot.'),
 step('Keep a recoverable result',['Commit the deliberate trial change after inspecting it. Review the short history and both commit messages.','Record the repository root, current branch and latest commit ID. Keep the folder for the GitHub, review and worktree lessons.','No push was needed: confirm that local commits and remote publication are separate.'],'You can find the recorded work without relying on the chat transcript.')],transfer:'For real changes, verify the repository root, inspect the diff, stage deliberately and check the resulting commit.'},
 {id:'github',area:'Developer workflows',title:'Push a branch and review a pull request',minutes:'About 25–35 min',source:'prs',references:['prs','githubCreatePr'],prerequisites:['git'],controls:['GitHub repository','Remote / Push','Pull request','Files changed / Checks','Merge / Update local'],summary:'Publish a trial branch to your own repository, inspect its PR and merge only the reviewed change.',steps:[
 {title:'A remote and a PR are separate objects',body:['GitHub hosts a remote repository. Pushing uploads commits; a pull request proposes bringing one branch’s change into another.','Use a new practice repository you own with only fictional files. The Git lesson’s local commit history is suitable. Do not push private documents or this course’s unreviewed source as part of a practice exercise.'],expect:'You know the local repository, remote owner and proposed branch change.'},
 step('Set up the intended remote',['Create an empty repository under your GitHub account with a deliberate visibility choice. Inspect its exact owner/name and clone/remote URL.','In the local trial folder, let the assistant inspect existing remotes before adding the intended one. Authenticate through the supported GitHub flow, never by putting a token into chat.','Push the initial/base branch and inspect its files and commit ID on GitHub.'],'You verified the remote target and a real uploaded snapshot.'),
 step('Open a focused pull request',['On a separate trial branch, change one packing item, inspect its diff, commit and push that branch.','Use the app’s PR action, assistant or GitHub’s Compare & pull request to open a draft PR against the actual base branch.','Inspect base/head names, title, description and Files changed. The PR should contain only your intended packing edit.'],'You verified the proposal and its source/destination branches.'),
 step('Review before merging',['Inspect any configured checks. If none exist, say no automated checks are configured rather than calling them passed.','Review the final diff and any comments. Amend the branch if the change is wrong, then recheck the updated PR revision.','When you want the reviewed trial change applied, mark ready and merge through an allowed method. If rules block it, inspect the stated requirement rather than bypass it.'],'You made a merge decision based on the actual revision and checks.'),
 step('Update the local base',['Switch back to the local base branch with a clean working state and fetch/pull the merged result using the app or assistant.','Inspect the local file and history against GitHub. Delete only a disposable merged trial branch if desired.','Keep the practice repository for later lessons; merging on GitHub did not automatically refresh your local files.'],'You verified the complete local-to-remote-and-back cycle.')],transfer:'Before a real PR, inspect target branches, final diff and checks, then update your local checkout after merge.'},
 {id:'review',area:'Developer workflows',title:'Run Code Review and verify a finding',minutes:'About 15–20 min',source:'review',prerequisites:['git'],controls:['/review','Review uncommitted changes','Finding / diff','Repair','Regression check'],summary:'Review a disclosed arithmetic defect, reproduce it and verify a repair without posting external comments.',steps:[
 {title:'A review finding needs evidence',body:['A review inspects a specified revision or change. Its findings are proposals to verify, not automatic proof of a bug or a merge approval.','Use your practice Git repository. Create a tiny trial function remainingBudget that deliberately returns budget + spend. The required behavior is subtraction: inputs 60 and 50 must return 10. This is an intentionally disclosed defect.'],expect:'You know the intended behavior and the defect you will test.'},
 step('Prepare and select the review scope',['Ask the assistant to add the tiny function in a clearly named trial source file and a runnable assertion for the expected result 10. Keep them uncommitted for this review.','Inspect the diff, then type /review and choose Review uncommitted changes. Do not ask for edits during this review pass.','Inspect which files/revision the reviewer actually considered.'],'You started a real review of the intended changes.','If /review is absent, verify this is a Git checkout. A general explanation of code can help but is not a trial of the review control.'),
 step('Reproduce before accepting',['Open the finding, if one was reported, and inspect its referenced file and lines.','Run the trial assertion through the assistant or terminal and inspect the actual failing result. If the review missed it, reproduce it yourself and report that miss honestly.','Distinguish the reviewer’s claim from the executed evidence and expected arithmetic.'],'You verified the defect independently of the review wording.'),
 step('Repair and recheck',['Authorize a minimal repair to subtraction, inspect the new diff and rerun the assertion. Test zero spend and spend greater than budget too.','Run a focused review of the final change if needed and inspect any remaining findings.','Commit only the intended trial files if keeping them. This local review did not post GitHub comments, approve or merge a PR.'],'You verified the repair against behavior and the final revision.')],transfer:'For real findings, identify the trigger, reproduce the behavior and inspect the repair before sharing a review decision.'},
 {id:'worktrees',area:'Developer workflows',title:'Try an isolated Git worktree',minutes:'About 15–20 min',source:'appWorktrees',prerequisites:['git'],controls:['Worktree selector / /worktree','Starting ref','Workspace path','Branch / diff','Archive worktree'],summary:'Create an isolated checkout, make a trial edit and verify the original checkout stays separate.',steps:[
 {title:'Separate files, shared repository history',body:['A worktree is another checkout of the same Git repository at a different path. It can isolate parallel edits; it is not a separate cloud computer.','Use your clean practice repository with at least one commit. Note its current path, branch and packing-list contents.'],expect:'You know which original checkout you will compare with the worktree.'},
 step('Create from an explicit starting point',['Use the app’s Worktree option or /worktree where available. Choose the intended repository and starting commit/base branch.','Inspect the returned workspace path and whether it starts on a branch or detached commit. Do not assume the app copied uncommitted files.','Open a chat/file view in that worktree and verify its initial packing-list contents.'],'You can identify the new checkout and its actual starting state.'),
 step('Make and compare an isolated edit',['In the worktree, change one packing item and inspect its diff.','Return to the original checkout and read the same file. It should still reflect its own working state; inspect rather than infer isolation from a chat title.','Commit the intended worktree edit if keeping it, and record its commit ID and branch/ref.'],'You verified separate working files and a recoverable change.'),
 step('Preserve before cleanup',['Choose how to retain the change: keep its branch/commit, transfer it through the app’s supported handoff/PR flow, or deliberately leave it as a disposable trial.','Inspect the app’s archive/remove warning and verify that needed files and commits are recoverable before removing the checkout. Do not use recursive shell deletion as a shortcut.','Reopen the original project and confirm its path and status.'],'You cleaned up only after preserving wanted work.')],transfer:'Give concurrent coding tasks separate checkouts, then inspect how their commits will be integrated.'}
 );
 lessons.push(
 {id:'cloud',area:'Developer workflows',title:'Run a repository task in Codex Cloud',minutes:'About 20–30 min plus setup',source:'cloudEnvironments',prerequisites:['github'],controls:['Work in → Cloud','Select / Create environment','Setup results','Publish environment','Task result / diff'],summary:'Prepare a trial repository environment, run a bounded task and inspect its remote output.',steps:[
 {title:'The cloud needs its own source and setup',body:['Codex Cloud runs repository work in a configured environment. Your local files, unsaved edits and installed tools are not automatically its starting state.','Use your own fictional practice repository on GitHub. Choose a small task: add a clear Usage section to its README, preserving existing content, with no merge or application deployment.'],expect:'You know the repository revision and intended remote change.'},
 step('Create and inspect an environment',['In a new task, select Work in → Cloud → Select environment → Create environment where available.','Select only the intended GitHub practice repository and inspect any required connection. Choose Get started and read the reported setup/tool checks.','Supply only the versions or commands the trial needs. Inspect missing access or failed setup before continuing. Publish the environment when its setup is ready; this is environment setup, not publishing a website.'],'You have an identifiable published coding environment.','If Cloud or repository access is unavailable, record that. A local task with the same prompt does not demonstrate cloud execution.'),
 step('Run against an identified revision',['Start a Cloud task in that environment. Check its repository and branch/commit before requesting the README Usage section.','Inspect the running task’s activity and environment identity. Do not assume an absent local file was uploaded.','Wait for completion or respond to an actual setup question. A missing dependency is a setup problem to inspect, not evidence the code is correct.'],'You can trace the task to the selected source and environment.'),
 step('Review the output and bring it back deliberately',['Open the result/diff and inspect the exact README change and any checks actually executed.','Compare it with the current GitHub/local revision; avoid silently overwriting work that changed after the task started.','Use the supported branch/PR or local-application flow only when you want to keep the change. Review before merging, and inspect your local file after updating.'],'You verified the cloud result and understood that integration is a separate step.')],transfer:'For cloud work, identify source, environment, checks and integration path before relying on a reported completion.'},
 {id:'hooks',area:'Developer workflows',title:'Install, trigger and disable a local lifecycle hook',minutes:'About 20–30 min',source:'hooks',prerequisites:['git'],controls:['Project .codex/hooks.json','SessionStart event','Trust review','Fresh chat','Marker log'],summary:'Configure a project-only marker hook, observe its actual event and remove the trial configuration.',steps:[
 {title:'A hook runs code at a configured event',body:['A lifecycle hook is executable configuration, not an ordinary reminder in a prompt. It must match a supported event and be trusted in the environment where it runs.','Use only the practice Git repository. The trial SessionStart hook should append the literal text hook-trial to a dedicated local log, consume input without storing it, emit an empty JSON object and exit successfully. It must not block actions or contact a network.'],expect:'You have a narrowly defined event, behavior and output to inspect.'},
 step('Prepare and review the configuration',['Ask the coding assistant to inspect existing project hook sources first, then prepare a minimal Windows-compatible script and project-local .codex/hooks.json entry for SessionStart using the official schema.','Inspect the exact script, command path and event configuration before enabling it. Keep existing hooks intact; do not install this in user-wide settings.','Have the assistant run the script once manually and verify the literal log line, valid empty JSON output and successful exit. Label this as a script check, not an event-triggered run.'],'You reviewed and manually checked the actual code.','If hooks are managed, unsupported or blocked by project trust, record unavailable instead of weakening unrelated controls.'),
 step('Trigger the real event',['Complete the supported trust/reload flow for your own trial hook. Note the log’s current line count.','Start a fresh chat in that same trusted project, which should trigger SessionStart. Inspect hook activity and the new marker log line.','If nothing ran, inspect the loaded config layer, event support, script path and trust decision. Do not count another manual invocation as a hook trigger.'],'You verified an actual lifecycle-triggered execution or recorded its failure.'),
 step('Disable and confirm',['Remove only the trial hook entry or use its supported disable mechanism. Reload/restart as required by the current client.','Start another fresh chat and inspect whether the trial log remains unchanged. Preserve other hooks and keep the script/log only if wanted.','Inspect Git status so trial configuration or logs are not accidentally committed with unrelated work.'],'You checked both activation and deactivation of the trial hook.')],transfer:'Treat hooks as reviewed code: narrow their event and effects, inspect a real trigger and test cleanup.'},
 {id:'subagents',area:'Coordinate work',title:'Delegate bounded work to subagents',minutes:'About 12–18 min',source:'subagents',controls:['Explicit delegation','Subagent activity / thread','Status / stop','Returned result'],summary:'Split two read-only checks, inspect agent activity and combine their evidence.',steps:[
 {title:'Delegate independent pieces with an output contract',body:['A subagent is a delegated worker whose result returns to the main chat. It is different from opening another user-owned chat. More agents can add cost and coordination overhead.','Use a fictional picnic plan: four people, Saturday noon, budget 60, costs 18 + 12 + 20, meeting place undecided. Assign one worker to check arithmetic and another to find missing decisions; neither needs file edits or external actions.'],expect:'You can explain the division of work and expected return from each worker.'},
 step('Request and inspect delegation',['In a supported Work/Codex chat, explicitly request two subagents with those separate roles and read-only boundaries. Ask the main agent to wait for both before summarizing.','Open the surfaced activity or agent threads and inspect each assignment and state.','If the surface instead completes sequentially without agent activity, keep that result but do not call it a subagent trial.'],'You verified actual delegation.','If agents are unavailable, record unavailable; a response written under two role headings is not proof of two workers.'),
 step('Check intermediate and returned evidence',['Inspect each worker’s result. The arithmetic should give cost 50 and reserve 10; the missing-decision check should notice the unresolved meeting place.','Check the main summary against both results. Ask it to resolve a contradiction using the source values rather than a vote.','Locate the stop control for an active worker if available; stop unnecessary trial work rather than spawn extras just to test the button.'],'You reviewed the delegated evidence and its integration.'),
 step('Decide whether it helped',['Check that no unexpected write or external action occurred.','Compare the overhead with this small task and name a larger independent investigation where delegation could help.','Record what context was supplied explicitly; do not assume each worker saw every message or local file.'],'You can judge when delegation is worth its cost and coordination.')],transfer:'Give agents bounded roles, relevant context, clear outputs and an explicit instruction about waiting and integration.'},
 {id:'model-handoff',area:'Coordinate work',title:'Hand a reviewed plan to another model',minutes:'About 15–20 min',source:'models',references:['models','pricing'],prerequisites:['plan-mode'],controls:['Model / Power picker','Plan review','New chat / model switch','Implementation diff','Usage indicators'],summary:'Plan a small checklist improvement, hand it off explicitly and compare the implemented result.',steps:[
 {title:'A handoff must carry decisions and checks',body:['You can use one available model for planning and another for implementation. Lower-cost settings do not guarantee lower total usage if repair and repeated context dominate.','Use a local checklist page in your practice folder. The change is a checked-item count and Reset button, with keyboard access and no external dependencies.'],expect:'You have a small implementation task and observable acceptance checks.'},
 step('Make and review the plan',['Choose an available model/settings for planning and record their actual labels. Use Plan mode to inspect the checklist and propose the change.','Review affected files, constraints, expected behavior and how to verify it. Resolve missing choices before handoff.','Write a compact handoff containing the agreed plan, file paths/revision, constraints and checks.'],'You have a usable plan rather than only a model’s reputation.'),
 step('Choose the implementer deliberately',['Select the intended second available model/settings or start a separate chat with them in the same practice project.','Supply the reviewed handoff explicitly. If the second chat lacks the relevant files or context, fix that before implementation.','Direct implementation of the accepted scope. Inspect the selected model label instead of assuming another chat uses different defaults.'],'The implementation runs with identified settings and relevant context.'),
 step('Judge the actual result',['Inspect the diff, open the page and test two checked items, Reset and keyboard access. Repair an observed mismatch if needed.','Inspect available usage information, recognizing that shared account windows and tool work may prevent a precise per-model comparison.','Record quality, time and repair effort. Do not claim token savings merely because the second model has a lower advertised rate.'],'You assessed the complete handoff against behavior and available cost evidence.')],transfer:'Use model handoffs when the plan is stable and context can be transferred clearly, then verify the implementation independently.'},
 {id:'parallel-chats',area:'Coordinate work',title:'Coordinate parallel chats and a controlled handoff',minutes:'About 15–20 min',source:'projects',references:['projects','goals'],controls:['New chat','Chat names / IDs','Activity','Explicit message destination','Wait / return'],summary:'Run two independent tasks, verify their separate context and combine the results.',steps:[
 {title:'Each chat needs its own brief',body:['Parallel chats are separate conversations. Keeping them in one project can share project sources but does not automatically share their full transcripts.','Use the fictional picnic plan from the subagent lesson. One chat checks budget arithmetic; another proposes a packing list. Neither writes files or messages anyone.'],expect:'You can identify two independent outputs and a clear integration task.'},
 step('Start and identify both chats',['Create two chats in a trial project and give them distinct names such as Budget check and Packing list. Supply the necessary fictional facts to each.','Start both tasks and inspect their actual running/completed state in Activity or the chat list.','Record each destination name/ID. Do not let two chats modify the same working files; use worktrees for concurrent code edits.'],'You can locate each independent task and its input.'),
 step('Authorize one explicit handoff',['In the coordinating chat, explicitly authorize sending the verified budget result to the identified Packing list chat, with the exact information and purpose.','If inter-chat messaging is supported, inspect the sent destination and received message in the target chat. If not, copy the result yourself and record that it was a manual handoff.','Have the target acknowledge the budget constraint before continuing. Do not assume a quoted message grants permission to reply elsewhere.'],'You distinguished an actual message delivery from shared project context or manual copying.'),
 step('Wait and integrate',['Ask the coordinator to wait for the relevant results where supported, then inspect the actual completed messages.','Compare the final packing suggestion with the budget and source facts. Resolve contradictions before using it.','Stop unused trial work and keep only chats you need. Messaging/waiting support varies; record any unavailable part separately.'],'You verified receipt, completion and a combined result.')],transfer:'For parallel work, identify owners and destinations, transfer a compact contract and check the final integration.'},
 {id:'events',area:'Coordinate work',title:'Try an event-triggered workflow and stop it',minutes:'About 15–25 min',source:'mcpEvents',prerequisites:['connections'],controls:['Event-capable plugin','Cloud Work','Event subscription','Trigger activity','Stop monitoring'],summary:'Monitor one authorized trial resource, cause a real event and verify the resulting action.',steps:[
 {title:'An event is different from a clock',body:['An event-triggered task reacts to a supported source update. A timed schedule or repeated polling request is not evidence of event delivery.','You need an installed, connected plugin that actually exposes a suitable event, such as comments on a document you control. MCP Events requires supporting server capabilities; a generic storage connection does not guarantee them.'],expect:'You can name the source event, resource and action, or identify that the capability is unavailable.'},
 step('Inspect the event before subscribing',['In an eligible Cloud Work chat or dot, inspect the plugin page’s exposed events and current account access. Choose one test document or resource you own.','Read the event’s supported filters. Define a narrow trial: when a new comment contains a unique marker, summarize it in this chat only.','If no matching event exists, record unavailable. Do not replace it with a schedule and claim the event feature was tested.'],'You have an actual supported event and a bounded action.'),
 step('Subscribe and generate one event',['Request the subscription for that exact resource and marker. Inspect the saved subscription/confirmation and any relevant activity.','In the source app, create one fictional comment containing the marker. Note its time and resource identity.','Wait for delivery and inspect the received action. Compare its source, content and time; investigate missing or duplicate delivery rather than inferring success.'],'You verified one real event and the resulting task action.'),
 step('Stop and inspect cleanup',['Stop monitoring through the owning chat/task controls and inspect unsubscribe or stopped status where exposed.','Add a second distinct fictional test marker if appropriate and observe whether it starts new work. A short quiet period alone is not proof of permanent revocation; inspect the saved state too.','Remove your own trial comments if desired and keep unrelated subscriptions intact.'],'You checked both the active workflow and its final subscription state.')],transfer:'Use narrow event filters and inspect a real trigger, result and stop state before leaving an automation active.'},
 {id:'dots',area:'Additional capabilities',title:'Set up a dot and inspect an assigned task',minutes:'About 15–20 min',source:'dotsGuide',references:['dotsGuide','dotSetup','dotControls'],controls:['Your dot','Profile / setup','Activity','Assigned task','Stop / ongoing responsibilities'],summary:'Give an eligible dot a small bounded task, inspect its activity and manage ongoing work.',steps:[
 {title:'Check availability before setup',body:['A dot is an always-on personal agent with its own cloud environment and task coordination. It is different from a Pet or an ordinary scheduled message.','Availability is limited by plan, region, age, rollout and workspace settings. Check your actual account and current access guide. Do not upgrade solely for this lesson; mark unavailable if access is absent.'],expect:'You can distinguish a dot from the interface companion and identify actual access.'},
 step('Create or inspect your dot',['Open Your dot or the supported setup entry. If creating one, choose a name and inspect its profile and available controls.','Leave external app and local-computer connections off for this first trial unless already deliberately configured.','Inspect which memory/context and task capabilities the profile describes; a messaging channel does not itself grant access to its app’s private data.'],'You know which agent and access are involved.'),
 step('Assign a bounded task',['Ask for three picnic ideas using fictional constraints, with no bookings, messages or ongoing monitoring.','Open the dot’s Activity and any delegated task it actually creates. Inspect where the work ran and the result. A trivial response may not create a separate task.','Check the ideas against the constraints and request one correction if needed.'],'You checked the actual work rather than inferring delegation or access from its wording.'),
 step('Inspect ongoing work and stop the trial',['Review Activity, responsibilities and any recurring work in the dot’s owning controls.','If your trial created continuing work, stop that specific task/responsibility and inspect its saved state. Do not delete unrelated context or connections.','Note where you would inspect permissions and revoke a local-computer connection if you later enabled one.'],'You can find the agent’s work and distinguish a one-time result from an ongoing responsibility.')],transfer:'Give a dot a clear outcome and boundaries, inspect delegated activity and review the ongoing work you leave active.'},
 {id:'space',area:'Additional capabilities',title:'Build a working page in ChatGPT Space',minutes:'About 15–20 min',source:'spacePages',references:['spacePages','spaceGuide'],controls:['Space → New page','Block / menu','Selected text → Ask for change','Pages list','Sharing controls'],summary:'Create a picnic plan page, edit one passage with AI and verify the saved page and audience.',steps:[
 {title:'A page is an editable working document',body:['Space pages combine writing, structure and supported interactive blocks. They are not the same object as a chat, Site deployment or local Markdown file.','Use a fictional picnic plan with headings Decisions, Open questions and Tasks. No collaborator invitation is needed for the basic trial.'],expect:'You know what belongs on the page and which object you are creating.'},
 step('Create and structure a page',['If Space is available, select New page and name it Picnic planning trial. Type the three headings and a few fictional items.','Use the / block menu to insert a checklist or table offered by your editor. Inspect the actual saved content.','Return to Pages and reopen the named page to check persistence.'],'You created a real page and found it again.','If Space or page editing is unavailable, record unavailable. Saving a note in a chat is useful but not a Space page trial.'),
 step('Edit a selected passage',['Select one paragraph and choose Ask for change where offered. Request shorter wording while keeping the fictional date and budget unchanged.','Inspect the changed passage in place and compare the facts. Use undo/revision controls if the change is wrong.','Try a supported reference to another source only if you deliberately want that context; do not assume linking also shares its permissions.'],'You verified an AI edit within the page itself.'),
 step('Inspect audience and close the loop',['Open the page’s sharing controls and read who can access it. Keep the intended private/test audience; do not invite anyone for this basic trial.','Reopen the page once more and check the final wording and checklist/table state.','If you later collaborate, test the intended role from an authorized recipient account. Editing a page and granting access are separate decisions.'],'You verified the saved object and its actual audience.')],transfer:'Use a page for an evolving plan, review edits in place and inspect permissions before collaboration.'}
 );
 const api={lessons};if(typeof module!=='undefined')module.exports=api;else root.QuestRemainingFeatureLessons=api;
})(typeof window!=='undefined'?window:globalThis);
